// Pure archive encoding shared by the main page and file-packing worker.
const batchEsc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function makeBatch3MF(coasters,template){
 if(!template)throw Error('Choose a Bambu printer project template first.');if(!coasters.length)throw Error('Convert at least one coaster first.');if(coasters.length>MAX_BATCH_IMAGES)throw Error('CoasterPrint limits batches to 10 coasters per project. Use a smaller batch.');
 const palette=[...new Set(coasters.flatMap(item=>{const result=item.stl;return [batchBaseColor(result),...result.parts.map(p=>batchColorHex(p.fill))];}))];
 const config=JSON.parse(JSON.stringify(template.config)),esc=batchEsc;assignProjectPalette(config,palette);for(const key of ['wipe_tower_x','wipe_tower_y'])if(Array.isArray(config[key])&&config[key].length)config[key]=Array(coasters.length).fill(config[key][0]);const objects=[],assemblies=[],build=[],modelConfigs=[],plates=[],allMaterials=[],materialIndices=new Map();let nextID=1;const columns=Math.ceil(Math.sqrt(coasters.length));const plateSummary=[];
 const transforms=[];
 for(let index=0;index<coasters.length;index++){
  const item=coasters[index],result=item.stl,box=result.dimensions,w=box.max[0]-box.min[0],h=box.max[1]-box.min[1];if(w>template.width-10||h>template.depth-10)throw Error(item.file.name+': coaster does not fit this template’s plate with a 5 mm margin. Reduce its width and rebuild.');
  const parentID=nextID++,name=item.file.name.replace(/\.[^.]+$/,'');const cols=columns;const originX=(index%cols)*template.width*1.2,originY=-Math.floor(index/cols)*template.depth*1.2;const x=originX+template.minX+(template.width-w)/2-box.min[0],y=originY+template.minY+(template.depth-h)/2-box.min[1],z=-box.min[2];const transform='1 0 0 0 1 0 0 0 1 '+[x,y,z].join(' ');transforms.push({parentID,transform});
  const members=[{name:'Base '+result.baseMM+' mm',fill:batchBaseColor(result),buffer:result.base.buffer},...result.parts.map(p=>({name:'Color '+String(p.index).padStart(2,'0')+' '+batchColorHex(p.fill),fill:batchColorHex(p.fill),buffer:p.buffer}))];const componentRefs=[],partMetadata=[];let faceCount=0;
  for(const part of members){const id=nextID++;if(!materialIndices.has(part.fill)){materialIndices.set(part.fill,allMaterials.length);allMaterials.push('<base name="'+esc(part.name)+'" displaycolor="'+part.fill+'FF"/>');}const materialIndex=materialIndices.get(part.fill);const mesh=batchSTLMesh(part.buffer);faceCount+=mesh.count;objects.push('<object id="'+id+'" name="'+esc(part.name)+'" type="model" pid="2147483000" pindex="'+materialIndex+'"><mesh>'+mesh.xml+'</mesh></object>');componentRefs.push('<component objectid="'+id+'"/>');
   const extruder=palette.indexOf(part.fill)+1;
   partMetadata.push('<part id="'+id+'" subtype="normal_part"><metadata key="name" value="'+esc(part.name)+'"/><metadata key="extruder" value="'+extruder+'"/><mesh_stat face_count="'+mesh.count+'" edges_fixed="0" degenerate_facets="0" facets_removed="0" facets_reversed="0" backwards_edges="0"/></part>');}
  assemblies.push('<object id="'+parentID+'" name="'+esc(name)+'" type="model"><components>'+componentRefs.join('')+'</components></object>');build.push('<item objectid="'+parentID+'" transform="'+transform+'"/>');modelConfigs.push('<object id="'+parentID+'"><metadata key="name" value="'+esc(name)+'"/><metadata key="extruder" value="1"/><metadata face_count="'+faceCount+'"/>'+partMetadata.join('')+'</object>');
  plates.push('<plate><metadata key="plater_id" value="'+(index+1)+'"/><metadata key="plater_name" value="'+esc(name)+'"/><metadata key="locked" value="false"/><model_instance><metadata key="object_id" value="'+parentID+'"/><metadata key="instance_id" value="0"/><metadata key="identify_id" value="'+(1000+index)+'"/></model_instance></plate>');plateSummary.push({plate:index+1,name,objectID:parentID,widthMM:w,depthMM:h,parts:members.length,origin:[originX,originY],translation:[x,y,z]});
 }
 // Bambu 2.8 skips all project/plate settings without a parsed BambuStudio Application version.
 // Keep the true generator explicit alongside the required project-dialect compatibility marker.
 const model='<?xml version="1.0" encoding="UTF-8"?><model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02" xmlns:BambuStudio="http://schemas.bambulab.com/package/2021"><metadata name="Application">BambuStudio-02.08.02.61</metadata><metadata name="Description">Generated by CoasterPrint r27</metadata><metadata name="BambuStudio:3mfVersion">1</metadata><metadata name="Title">CoasterPrint colored coaster project</metadata><resources><basematerials id="2147483000">'+allMaterials.join('')+'</basematerials>'+objects.join('')+assemblies.join('')+'</resources><build>'+build.join('')+'</build></model>';
 const settings='<?xml version="1.0" encoding="UTF-8"?><config>'+modelConfigs.join('')+plates.join('')+'<assemble>'+transforms.map(t=>'<assemble_item object_id="'+t.parentID+'" instance_id="0" transform="'+t.transform+'" offset="0 0 0"/>').join('')+'</assemble></config>';
 const files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/><Default Extension="config" ContentType="application/xml"/><Default Extension="json" ContentType="application/json"/></Types>',
 '_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>',
 '3D/3dmodel.model':model,'Metadata/model_settings.config':settings,'Metadata/project_settings.config':JSON.stringify(config),'Metadata/coasterprint-plates.json':JSON.stringify({application:'CoasterPrint',printer:template.printer,colors:palette.map((hex,index)=>({slot:index+1,hex})),columns,plates:plateSummary},null,2)};
 return fflate.zipSync(Object.fromEntries(Object.entries(files).map(([k,v])=>[k,fflate.strToU8(v)])),{level:6});
}
function batchBaseColor(result){return batchColorHex(result.baseFill||result.parts[0]?.fill||'#D0D0D0');}
function batchColorHex(fill){const m=String(fill).match(/[\d.]+/g);return m&&m.length>=3?'#'+m.slice(0,3).map(n=>Math.round(+n).toString(16).padStart(2,'0')).join('').toUpperCase():/^#[\da-f]{6}$/i.test(fill)?fill.toUpperCase():'#808080';}
function batchSTLMesh(buffer){const view=new DataView(buffer),count=view.getUint32(80,true),vertices=[],triangles=[],map=new Map();for(let i=0;i<count;i++){const ids=[];for(let k=0;k<3;k++){const o=84+i*50+12+k*12,p=[view.getFloat32(o,true),view.getFloat32(o+4,true),view.getFloat32(o+8,true)],key=p.join(',');if(!map.has(key)){map.set(key,vertices.length);vertices.push('<vertex x="'+p[0]+'" y="'+p[1]+'" z="'+p[2]+'"/>');}ids.push(map.get(key));}triangles.push('<triangle v1="'+ids[0]+'" v2="'+ids[1]+'" v3="'+ids[2]+'"/>');}return {count,xml:'<vertices>'+vertices.join('')+'</vertices><triangles>'+triangles.join('')+'</triangles>'};}
function partsArchive(item,result){const files={};const baseName='base-'+result.baseMM+'mm.stl';files[baseName]=new Uint8Array(result.base.buffer);const colors=result.parts.map(part=>{const rgb=(part.fill.match(/[\d.]+/g)||[]).slice(0,3).map(Number);const hex=rgb.length===3?'#'+rgb.map(n=>Math.round(n).toString(16).padStart(2,'0')).join(''):part.fill;const name='image-color-'+String(part.index).padStart(2,'0')+'-'+hex.replace('#','')+'.stl';files[name]=new Uint8Array(part.buffer);return {file:name,svgColor:part.fill,hex,zStartMM:result.baseMM,heightMM:result.topMM};});files['colors.json']=fflate.strToU8(JSON.stringify({units:'mm',dimensions:result.dimensions,base:{file:baseName,zStartMM:0,heightMM:result.baseMM},colors},null,2));files['IMPORT-INTO-BAMBU.txt']=fflate.strToU8('COASTERPRINT — ALIGNED PRINT PARTS\n\nExtract this ZIP. Select the base STL and ALL image-color STL files, then drag them into Bambu Studio together. When asked, load them as a SINGLE object with multiple parts. This preserves the shared coordinates and the raised layer height. Do not import or auto-arrange each file separately: the slicer may drop each part onto the plate.\n\nAssign a filament to the base and each image color part. colors.json lists the SVG colors. STL itself stores geometry, not colors.\n\nBase: '+result.baseMM+' mm, Z=0 to '+result.baseMM+'. Raised image: '+result.topMM+' mm, Z='+result.baseMM+' to '+(result.baseMM+result.topMM)+'. Width: '+result.widthMM+' mm.\n\nEach color has its own STL part. Assign filaments by part rather than using the fill-paint tool.\n');return fflate.zipSync(files,{level:6});}

function makePartsBatch(items){
 if(items.length===1)return partsArchive(items[0],items[0].stl);
 const files={};
 for(let index=0;index<items.length;index++){
  const item=items[index],name=String(item.file.name).replace(/\.[^.]+$/,'').replace(/[^a-z0-9_-]/gi,'_').slice(0,80)||'coaster';
  for(const [path,bytes] of Object.entries(fflate.unzipSync(partsArchive(item,item.stl))))files[String(index+1).padStart(2,'0')+'-'+name+'/'+path]=bytes;
 }
 files['START-HERE.txt']=fflate.strToU8('COASTERPRINT — FREE STL PARTS\n\nExtract this ZIP. Each coaster has its own folder. For each coaster, select its base and all image-color STL files together. In Bambu Studio, import as one object with multiple parts. Assign a filament to each part. Do not import parts individually or auto-arrange them. Repeat for the other coaster folders.\n');
 return fflate.zipSync(files,{level:6});
}
